  void _applyUri(PaymentUriData paymentData) {
    try {
      // auto fill address
      _address = paymentData.address.trim();

      // shield memo
      memoController.text = truncateUtf8(
        paymentData.additionalParams['memo'] ?? "",
        kPivxMaxMemoBytes,
      );

      // autofill notes field
      if (paymentData.message != null) {
        noteController.text = paymentData.message!;
      } else if (paymentData.label != null) {
        noteController.text = paymentData.label!;
      }

      // autofill amount field
      if (paymentData.amount != null) {
        final Amount amount = Decimal.parse(paymentData.amount!)
            .toAmount(fractionDigits: coin.fractionDigits);
        cryptoAmountController.text = ref
            .read(pAmountFormatter(coin))
            .format(amount, withUnitName: false);
        ref.read(pSendAmount.notifier).state = amount;
      }

      _setValidAddressProviders(_address);

      // Assign controller.text last: it triggers onChanged.
      sendToController.text = _address!;

      setState(() {
        _addressToggleFlag = sendToController.text.isNotEmpty;
      });
    } catch (e, s) {
      Logging.instance.e(
        "Failed to apply uri in SendView: ",
        error: e,
        stackTrace: s,
      );
    }
  }

  void _setAddress(String content, {bool setController = true}) {
    if (setController) {
      sendToController.text = content;
    }
    _address = content;
  }

  Future<void> _pasteAddress() async {
    final ClipboardData? data = await clipboard.getData(Clipboard.kTextPlain);
    if (data?.text != null && data!.text!.isNotEmpty) {
      String content = data.text!.trim();
      if (content.contains("\n")) {
        content = content.substring(0, content.indexOf("\n")).trim();
      }

      try {
        final paymentData = AddressUtils.parsePaymentUri(
          content,
          logging: Logging.instance,
        );

        if (paymentData != null &&
            paymentData.coin?.uriScheme == coin.uriScheme) {
          _applyUri(paymentData);
        } else {
          sendToController.text = content;
          _address = content;

          _setValidAddressProviders(_address);
          setState(() {
            _addressToggleFlag = sendToController.text.isNotEmpty;
          });
        }
      } catch (e) {
        _setAddress(content);

        // Trigger validation after pasting.
        _setValidAddressProviders(_address);
        setState(() {
          _addressToggleFlag = sendToController.text.isNotEmpty;
        });
      }
    }
  }

  Future<void> _scanQr() async {
    try {
      if (FocusScope.of(context).hasFocus) {
        FocusScope.of(context).unfocus();
        await Future<void>.delayed(const Duration(milliseconds: 75));
      }
      if (!mounted) return;

      final qrResult = await ref.read(pBarcodeScanner).scan(context: context);

      Logging.instance.d("qrResult content: ${qrResult.rawContent}");
      if (qrResult.rawContent == null) return;

      final paymentData = AddressUtils.parsePaymentUri(
        qrResult.rawContent!,
        logging: Logging.instance,
      );

      if (paymentData != null &&
          paymentData.coin?.uriScheme == coin.uriScheme) {
        _applyUri(paymentData);
      } else {
        _address = qrResult.rawContent!.split("\n").first.trim();
        sendToController.text = _address ?? "";

        _setValidAddressProviders(_address);
        setState(() {
          _addressToggleFlag = sendToController.text.isNotEmpty;
        });
      }
    } on PlatformException catch (e, s) {
      if (mounted) {
        try {
          await checkCamPermDeniedMobileAndOpenAppSettings(
            context,
            logging: Logging.instance,
          );
        } catch (e, s) {
          Logging.instance.e(
            "Failed to check cam permissions",
            error: e,
            stackTrace: s,
          );
        }
      } else {
        Logging.instance.e(
          "Failed to get camera permissions while trying to scan qr code in SendView: ",
          error: e,
          stackTrace: s,
        );
      }
    }
  }

  void _fiatFieldChanged(String baseAmountString) {
    final baseAmount = Amount.tryParseFiatString(
      baseAmountString,
      locale: ref.read(localeServiceChangeNotifierProvider).locale,
    );
    final Amount? amount;
    if (baseAmount != null) {
      final _price = ref
          .read(priceAnd24hChangeNotifierProvider)
          .getPrice(coin)
          ?.value;

      if (_price == null || _price == Decimal.zero) {
        amount = 0.toAmountAsRaw(fractionDigits: coin.fractionDigits);
      } else {
        amount = baseAmount <= Amount.zero
            ? 0.toAmountAsRaw(fractionDigits: coin.fractionDigits)
            : (baseAmount.decimal / _price)
                  .toDecimal(scaleOnInfinitePrecision: coin.fractionDigits)
                  .toAmount(fractionDigits: coin.fractionDigits);
      }
      if (_cachedAmountToSend != null && _cachedAmountToSend == amount) {
        return;
      }
      _cachedAmountToSend = amount;

      final amountString = ref
          .read(pAmountFormatter(coin))
          .format(amount, withUnitName: false);

      _cryptoAmountChangeLock = true;
      cryptoAmountController.text = amountString;
      _cryptoAmountChangeLock = false;
    } else {
      amount = 0.toAmountAsRaw(fractionDigits: coin.fractionDigits);
      _cryptoAmountChangeLock = true;
      cryptoAmountController.text = "";
      _cryptoAmountChangeLock = false;
    }
    ref.read(pSendAmount.notifier).state = amount;
  }

  void _cryptoAmountChanged() async {
    if (!_cryptoAmountChangeLock) {
      final cryptoAmount = ref
          .read(pAmountFormatter(coin))
          .tryParse(cryptoAmountController.text);
      final Amount? amount;
      if (cryptoAmount != null) {
        amount = cryptoAmount;
        if (_cachedAmountToSend != null && _cachedAmountToSend == amount) {
          return;
        }
        _cachedAmountToSend = amount;

        final price = ref
            .read(priceAnd24hChangeNotifierProvider)
            .getPrice(coin)
            ?.value;

        if (price != null && price > Decimal.zero) {
          baseAmountController.text = (amount.decimal * price)
              .toAmount(fractionDigits: 2)
              .fiatString(
                locale: ref.read(localeServiceChangeNotifierProvider).locale,
              );
        }
      } else {
        amount = null;
        baseAmountController.text = "";
      }

      ref.read(pSendAmount.notifier).state = amount;

      _cryptoAmountChangedFeeUpdateTimer?.cancel();
      _cryptoAmountChangedFeeUpdateTimer = Timer(updateFeesTimerDuration, () {
        if (!_baseFocus.hasFocus) {
          setState(() {
            _calculateFeesFuture = calculateFees(
              amount ?? 0.toAmountAsRaw(fractionDigits: coin.fractionDigits),
            );
          });
        }
      });
    }
  }

  final updateFeesTimerDuration = const Duration(milliseconds: 500);

  Timer? _cryptoAmountChangedFeeUpdateTimer;
  Timer? _baseAmountChangedFeeUpdateTimer;

  void _baseAmountChanged() {
    _baseAmountChangedFeeUpdateTimer?.cancel();
    _baseAmountChangedFeeUpdateTimer = Timer(updateFeesTimerDuration, () {
      if (!_cryptoFocus.hasFocus) {
        setState(() {
          _calculateFeesFuture = calculateFees(
            ref.read(pSendAmount) == null
                ? 0.toAmountAsRaw(fractionDigits: coin.fractionDigits)
                : ref.read(pSendAmount)!,
          );
        });
      }
    });
  }

  /// The fee last shown, for coin control's "amount needed".
  late Amount _currentFee;

  void _setValidAddressProviders(String? address) {
    final wallet = ref.read(pWallets).getWallet(walletId);
    ref.read(pValidSendToAddress.notifier).state =
        wallet.cryptoCurrency.validateAddress(address ?? "") ||
        pivxNameFor(coin, address) != null;
  }

  /// PIVX.name names always point to shield addresses.
  bool get _sendsToShield =>
      (coin as Pivx).isShieldAddress(_address ?? "") ||
      pivxNameFor(coin, _address) != null;

  late Future<String> _calculateFeesFuture;

  Map<Amount, Amount> cachedFees = {};

  Future<String> calculateFees(Amount amount) async {
    final wallet = ref.read(pWallets).getWallet(walletId) as PivxWallet;
    final fromShield =
        ref.read(publicPrivateBalanceStateProvider) == BalanceType.private;
    final toShield = _sendsToShield;

    final Amount fee;
    if (fromShield || toShield) {
      // Shield fee depends on the selected balance and recipient type,
      // so it is not cached per amount.
      fee = await wallet.estimateShieldFee(
        amount: amount,
        fromShield: fromShield,
        toShield: toShield,
        selected: selectedUTXOs.isEmpty
            ? null
            : selectedUTXOs.map((e) => e.utxo).toSet(),
        subtractFee: _pivxSubtractFee,
      );
    } else {
      // PIVX has no fee market: every transparent send pays the relay
      // minimum (fast = average = slow).
      fee = cachedFees[amount] ??= await wallet.estimateFeeFor(
        amount,
        (await wallet.fees).medium,
      );
    }
    _currentFee = fee;
    return ref
        .read(pAmountFormatter(coin))
        .format(fee, withUnitName: true, indicatePrecisionLoss: false);
  }

  /// A Preview tap while one is running is ignored: two would build two
  /// transactions.
  bool _previewing = false;

  Future<void> _previewTransaction() async {
    if (_previewing) return;
    _previewing = true;
    try {
      await _preview();
    } finally {
      _previewing = false;
    }
  }

  Future<void> _preview() async {
    // wait for keyboard to disappear
    FocusScope.of(context).unfocus();
    await Future<void>.delayed(const Duration(milliseconds: 100));
    final wallet = ref.read(pWallets).getWallet(walletId);

    final Amount amount = ref.read(pSendAmount)!;
    final Amount availableBalance;
    switch (ref.read(publicPrivateBalanceStateProvider)) {
      case BalanceType.public:
        availableBalance = wallet.info.cachedBalance.spendable;
        break;
      case BalanceType.private:
        availableBalance = wallet.info.cachedBalanceSecondary.spendable;
        break;
    }

    final coinControlEnabled = ref
        .read(prefsChangeNotifierProvider)
        .enableCoinControl;

    if (!coinControlEnabled || selectedUTXOs.isEmpty) {
      // confirm send all
      if (amount == availableBalance) {
        bool? shouldSendAll;
        if (mounted) {
          shouldSendAll = await showDialog<bool>(
            context: context,
            useSafeArea: false,
            barrierDismissible: true,
            builder: (context) {
              return StackDialog(
                title: "Confirm send all",
                message: "You are about to send your entire balance. Would you like to continue?",
                leftButton: TextButton(
                  style: Theme.of(context)
                      .extension<StackColors>()!
                      .getSecondaryEnabledButtonStyle(context),
                  child: Text(
                    "Cancel",
                    style: STextStyles.button(context).copyWith(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .accentColorDark,
                    ),
                  ),
                  onPressed: () {
                    Navigator.of(context).pop(false);
                  },
                ),
                rightButton: TextButton(
                  style: Theme.of(context)
                      .extension<StackColors>()!
                      .getPrimaryEnabledButtonStyle(context),
                  child: Text("Yes", style: STextStyles.button(context)),
                  onPressed: () {
                    Navigator.of(context).pop(true);
                  },
                ),
              );
            },
          );
        }

        if (shouldSendAll == null || shouldSendAll == false) {
          // cancel preview
          return;
        }
      }
    }

    // A PIVX.name name: look it up and check it first. The transaction
    // pays the address that was proven, never the name's text.
    var recipient = _address!;
    PivxNameVerified? pivxName;
    final name = pivxNameFor(coin, _address);
    if (name != null) {
      if (!mounted) return;
      pivxName = await lookUpPivxNameForSend(
        context: context,
        coin: coin,
        name: name,
        contacts: ref.read(addressBookServiceProvider).contacts,
      );
      if (pivxName == null || !mounted) return;
      recipient = pivxName.address;
    }

    // The dialog's Cancel button closes the dialog itself.
    bool wasCancelled = false;
    try {
      if (mounted) {
        unawaited(
          showDialog<void>(
            context: context,
            useSafeArea: false,
            barrierDismissible: false,
            builder: (context) {
              return BuildingTransactionDialog(
                coin: wallet.info.coin,
                onCancel: () => wasCancelled = true,
              );
            },
          ),
        );
      }

      final time = Future<dynamic>.delayed(const Duration(milliseconds: 2500));

      final Future<TxData> txDataFuture;

      final memo =
          (coin as Pivx).isShieldAddress(recipient) &&
              memoController.text.isNotEmpty
          ? memoController.text
          : null;
      // Spending the private balance means spending shield notes.
      final pivxFromShield =
          ref.read(publicPrivateBalanceStateProvider) == BalanceType.private;
      final pivxOtherData = <String, dynamic>{
        if (pivxFromShield) kPivxFromShield: true,
        if (_pivxSubtractFee) kPivxSubtractFee: true,
        if (!pivxFromShield && _pivxChangeAddress != null)
          kPivxChangeAddress: _pivxChangeAddress,
        if (pivxFromShield && _pivxShieldChangeAddress != null)
          kPivxChangeAddress: _pivxShieldChangeAddress,
      };
      txDataFuture = wallet.prepareSend(
        txData: TxData(
          recipients: [
            TxRecipient(
              address: recipient,
              amount: amount,
              isChange: false,
              addressType: wallet.cryptoCurrency.getAddressType(recipient)!,
            ),
          ],
          memo: memo,
          feeRateType: FeeRateType.average,
          utxos: (coinControlEnabled && selectedUTXOs.isNotEmpty)
              ? selectedUTXOs
              : null,
          otherData: pivxOtherData.isEmpty ? null : jsonEncode(pivxOtherData),
        ),
      );

      final results = await Future.wait([txDataFuture, time]);

      TxData txData = results.first as TxData;

      if (!wasCancelled && mounted) {
        txData = txData.copyWith(
          note: noteController.text,
          noteOnChain: onChainNoteController.text,
        );

        // pop building dialog
        Navigator.of(context, rootNavigator: true).pop();

        unawaited(
          Navigator.of(context).push(
            RouteGenerator.getRoute(
              shouldUseMaterialRoute: RouteGenerator.useMaterialPageRoute,
              builder: (_) => ConfirmTransactionView(
                txData: txData,
                walletId: walletId,
                pivxName: pivxName,
                onSuccess: () {
                  if (mounted) {
                    clearSendForm();
                  }
                },
              ),
              settings: const RouteSettings(
                name: ConfirmTransactionView.routeName,
              ),
            ),
          ),
        );
      }
    } catch (e, s) {
      Logging.instance.e("$e\n$s", error: e, stackTrace: s);
      // Cancelled: the dialog is closed already, and the error is moot.
      if (mounted && !wasCancelled) {
        // pop building dialog
        Navigator.of(context, rootNavigator: true).pop();

        unawaited(
          showDialog<dynamic>(
            context: context,
            useSafeArea: false,
            barrierDismissible: true,
            builder: (context) {
              return StackDialog(
                title: "Transaction failed",
                message: e.toString(),
                rightButton: TextButton(
                  style: Theme.of(context)
                      .extension<StackColors>()!
                      .getSecondaryEnabledButtonStyle(context),
                  child: Text(
                    "Ok",
                    style: STextStyles.button(context).copyWith(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .accentColorDark,
                    ),
                  ),
                  onPressed: () {
                    Navigator.of(context).pop();
                  },
                ),
              );
            },
          ),
        );
      }
    }
  }

  void clearSendForm() {
    if (!mounted) {
      return;
    }
    sendToController.text = "";
    cryptoAmountController.text = "";
    baseAmountController.text = "";
    noteController.text = "";
    onChainNoteController.text = "";
    feeController.text = "";
    memoController.text = "";
    _address = "";
    _addressToggleFlag = false;
    setState(() {});
  }

  String _getSendAllTitle(
    bool showCoinControl,
    Set<StandardInput> selectedUTXOs,
  ) {
    if (showCoinControl && selectedUTXOs.isNotEmpty) {
      return "Send all selected";
    }

    return "Send all ${coin.ticker}";
  }

  Amount _selectedUtxosAmount(Set<StandardInput> utxos) => Amount(
    rawValue: utxos.map((e) => e.value).reduce((v, e) => v += e),
    fractionDigits: ref.read(pWalletCoin(walletId)).fractionDigits,
  );

  void _setPivxSubtractFee(bool value) {
    setState(() {
      _pivxSubtractFee = value;
      // Shield fees depend on how many notes the amount needs.
      _calculateFeesFuture = calculateFees(
        ref.read(pSendAmount) ??
            0.toAmountAsRaw(fractionDigits: coin.fractionDigits),
      );
    });
  }

  Future<void> _sendAllTapped(bool showCoinControl) async {
    // PIVX never takes the fee out of the amount silently: sending
    // everything ticks "Subtract fee from amount" where the user sees it.
    if (!_pivxSubtractFee) _setPivxSubtractFee(true);
    final Amount amount;

    if (showCoinControl && selectedUTXOs.isNotEmpty) {
      amount = _selectedUtxosAmount(selectedUTXOs);
    } else {
      switch (ref.read(publicPrivateBalanceStateProvider)) {
        case BalanceType.public:
          amount = ref.read(pWalletBalance(walletId)).spendable;
          break;

        case BalanceType.private:
          amount = ref.read(pWalletBalanceSecondary(walletId)).spendable;
          break;
      }
    }

    cryptoAmountController.text = ref
        .read(pAmountFormatter(coin))
        .format(amount, withUnitName: false);
    _cryptoAmountChanged();
  }

  /// Chosen change address for a send from [balance] (null: automatic).
  String? _pivxChange(BalanceType balance) => balance == BalanceType.private
      ? _pivxShieldChangeAddress
      : _pivxChangeAddress;

  @override
  void initState() {
    coin = widget.coin;

    _data = widget.autoFillData;
    walletId = widget.walletId;
    clipboard = widget.clipboard;

    _currentFee = 0.toAmountAsRaw(fractionDigits: coin.fractionDigits);

    _calculateFeesFuture = calculateFees(
      0.toAmountAsRaw(fractionDigits: coin.fractionDigits),
    );

    sendToController = TextEditingController();
    cryptoAmountController = TextEditingController();
    baseAmountController = TextEditingController();
    noteController = TextEditingController();
    onChainNoteController = TextEditingController();
    feeController = TextEditingController();
    memoController = TextEditingController();

    onCryptoAmountChanged = _cryptoAmountChanged;
    cryptoAmountController.addListener(onCryptoAmountChanged);
    baseAmountController.addListener(_baseAmountChanged);

    if (_data != null) {
      final hasAmount = _data.amount != null;
      if (hasAmount) {
        final amount = Amount.fromDecimal(
          _data.amount!,
          fractionDigits: coin.fractionDigits,
        );

        _cryptoAmountChangeLock = true;
        cryptoAmountController.text = ref
            .read(pAmountFormatter(coin))
            .format(amount, withUnitName: false);
        _cryptoAmountChangeLock = false;
      }
      sendToController.text = _data.contactLabel;
      _address = _data.address.trim();
      _addressToggleFlag = true;

      WidgetsBinding.instance.addPostFrameCallback((timeStamp) {
        if (hasAmount) {
          _cryptoAmountChanged();
        }
        _setValidAddressProviders(_address);
      });
    }

    if (widget.paymentUri != null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _applyUri(widget.paymentUri!);
      });
    }

    super.initState();
  }

  @override
  void dispose() {
    _cryptoAmountChangedFeeUpdateTimer?.cancel();
    _baseAmountChangedFeeUpdateTimer?.cancel();

    cryptoAmountController.removeListener(onCryptoAmountChanged);
    baseAmountController.removeListener(_baseAmountChanged);

    sendToController.dispose();
    cryptoAmountController.dispose();
    baseAmountController.dispose();
    noteController.dispose();
    onChainNoteController.dispose();
    feeController.dispose();
    memoController.dispose();

    _noteFocusNode.dispose();
    _pivxMemoFocusNode.dispose();
    _onChainNoteFocusNode.dispose();
    _addressFocusNode.dispose();
    _cryptoFocus.dispose();
    _baseFocus.dispose();
    _memoFocus.dispose();
    super.dispose();
  }

