                              ),
                              child: TextField(
                                autocorrect: Util.isDesktop ? false : true,
                                enableSuggestions: Util.isDesktop
                                    ? false
                                    : true,
                                controller: noteController,
                                focusNode: _noteFocusNode,
                                style: STextStyles.field(context),
                                onChanged: (_) => setState(() {}),
                                decoration:
                                    standardInputDecoration(
                                      coin is Pivx
                                          ? "Just for you: kept in your history, never sent"
                                          : "Type something...",
                                      _noteFocusNode,
                                      context,
                                    ).copyWith(
                                      suffixIcon: noteController.text.isNotEmpty
                                          ? Padding(
                                              padding: const EdgeInsets.only(
                                                right: 0,
                                              ),
                                              child: UnconstrainedBox(
                                                child: Row(
                                                  children: [
                                                    TextFieldIconButton(
                                                      child: const XIcon(),
                                                      onTap: () async {
                                                        setState(() {
                                                          noteController.text =
                                                              "";
                                                        });
                                                      },
                                                    ),
                                                  ],
                                                ),
                                              ),
                                            )
                                          : null,
                                    ),
                              ),
                            ),
                            const SizedBox(height: 12),
                            Text(
                              "Network fee (estimated)",
                              style: STextStyles.smallMed12(context),
                              textAlign: TextAlign.left,
                            ),
                            const SizedBox(height: 8),
                            // PIVX has no fee market: the fee is the
                            // network minimum, nothing to choose.
                            RoundedContainer(
                              color: Theme.of(context)
                                  .extension<StackColors>()!
                                  .textFieldDefaultBG,
                              padding: const EdgeInsets.symmetric(
                                horizontal: 12,
                                vertical: 14,
                              ),
                              child: FutureBuilder(
                                future: _calculateFeesFuture,
                                builder: (context, snapshot) {
                                  if (snapshot.connectionState ==
                                          ConnectionState.done &&
                                      snapshot.hasData) {
                                    return Text(
                                      "~${snapshot.data!}",
                                      style: STextStyles.itemSubtitle12(
                                        context,
                                      ),
                                    );
                                  }
                                  return AnimatedText(
                                    stringsToLoopThrough: stringsToLoopThrough,
                                    style: STextStyles.itemSubtitle(context),
                                  );
                                },
                              ),
                            ),
                            const Spacer(),
                            const SizedBox(height: 12),
                            TextButton(
                              onPressed:
                                  ref.watch(pPreviewTxButtonEnabled(coin))
                                  ? _previewTransaction
                                  : null,
                              style: ref.watch(pPreviewTxButtonEnabled(coin))
                                  ? Theme.of(context)
                                        .extension<StackColors>()!
                                        .getPrimaryEnabledButtonStyle(context)
                                  : Theme.of(context)
                                        .extension<StackColors>()!
                                        .getPrimaryDisabledButtonStyle(context),
                              child: Text(
                                "Preview",
                                style: STextStyles.button(context),
                              ),
                            ),
                            const SizedBox(height: 16),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
        ),
      ),
    );
  }
}
